import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"37、【家人】 離下巽上","description":"周易尚氏學 - 37、【家人】 離下巽上","frontmatter":{"title":"37、【家人】 離下巽上","description":"周易尚氏學 - 37、【家人】 離下巽上"},"headers":[],"relativePath":"classics/shangshi/042.md","filePath":"classics/shangshi/042.md"}'),s={name:"classics/shangshi/042.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_37、【家人】-離下巽上" tabindex="-1">37、【家人】 離下巽上 <a class="header-anchor" href="#_37、【家人】-離下巽上" aria-label="Permalink to “37、【家人】 離下巽上”">​</a></h1><p>歸藏曰散家人。卦以一陽一陰。散處於卦內。又上卦巽風。下卦火炎上。均有敬意。故以為名乎。馬融曰。家人以女為奧主。長女中女。各得其正。故曰利女貞。然象傳曰。男正位乎外。似家人兼男女言。特女尤利耳。又考太玄擬家人為居。雲踞膚赫赫。為物城郭。萬物鹹宅。是以家人初上爻皆陽。故曰膚。曰城郭。而人宅其中。故曰家人也。義似較各家為優。二四得正。承陽有應。故利於女子之佔也。</p><p>彖曰。家人女正位子內。男正位乎外。男女正。天地之大義也。家人有嚴君焉。父母之謂也。父父。子子。兄兄。弟弟。夫夫。婦婦。而家道正。正家而天下定矣。</p><p>女正位乎內謂二。男正位乎外謂五。二五者夫婦。即天地也。即父母也。父母皆得正位。故曰嚴君。嚴君者尊也。卦下五爻皆得正。故曰父父。子子。兄兄。弟弟。夫夫。婦婦。初震交。震為子。為兄。為夫。三艮爻互坎。坎艮皆為弟。巽為婦。父子兄弟夫婦皆得正。則家正。家齊則國治。故曰天下定。</p><p>象曰。風自火出。家人。君子以言有物。而行有恆。</p><p>巽木生火。火動生風。故曰風自火出。物。孔疏雲事也。按周禮地官。司門幾齣人之不物者。注。衣服視瞻。不與眾同。及所操物。不如品式者。然則不物即違常。即不法也。言有物者。即言不離乎經常也。</p><p>初九。閒有家。悔亡。</p><p>釋文。馬雲閒闌也。防也。離中虛外堅。故離有閒義。即太玄所謂為物城郭也。能閉其家。故侮亡也。荀鄭訓閒為閒習。似非。</p><h3 id="象曰。閒有家。志未變也。" tabindex="-1">象曰。閒有家。志未變也。 <a class="header-anchor" href="#象曰。閒有家。志未變也。" aria-label="Permalink to “象曰。閒有家。志未變也。”">​</a></h3><p>初應在四。四體坎。坎為志。志未變者。言初與四為正應。無敢或渝。所謂行有恆而家道正也。其以遂為說者。皆因不得解而穿鑿也。</p><p>六二。無攸遂。在中饋。貞吉。</p><p>禮月令百事乃遂。注遂猶成也。公羊傳桓八年。大夫無遂事。注遂專事也。坤道無成。六二應五承三。順以類可矣。不必專事也。故曰無攸遂。六二得中。故曰在中饋。饋餉也。周禮天官。膳夫掌王之饋。注進食於尊曰饋。在中饋者。言道順從。無敢專事。職供中饋。酒食是議也。貞吉者。卜問吉也。</p><h3 id="象曰。六二之吉。順以巽也。順以巽。言承三應五也。" tabindex="-1">象曰。六二之吉。順以巽也。順以巽。言承三應五也。 <a class="header-anchor" href="#象曰。六二之吉。順以巽也。順以巽。言承三應五也。" aria-label="Permalink to “象曰。六二之吉。順以巽也。順以巽。言承三應五也。”">​</a></h3><p>九三。家人高高（左口）。 悔歷吉。婦子嘻嘻。終吝。</p><p>釋文。高高（左口）。馬雲悅樂自得兒。荀作確確。按離外堅。荀讀是也。嘻嘻鄭雲驕佚笑樂之意。然同在一爻。吉吝不同者。蓋三居離上。離外堅。有堅確自守。安不忘危之意。故曰家人高高（左口）。高高（左口）則守正安常。故厲而古也。而三前臨巽風。巽為婦。為進退。為躁動。為聲應。故曰婦子嘻嘻。嘻嘻則悅而淫矣。故曰終吝。高高（左口）之象下取離。嘻嘻之象上取巽。誠以同此一爻。或吉或吝。必有其故。而光儒無言者。探測如此。</p><h3 id="象曰。家人高高-左口-。未失也。婦子嘻嘻。失家節也。" tabindex="-1">象曰。家人高高（左口）。未失也。婦子嘻嘻。失家節也。 <a class="header-anchor" href="#象曰。家人高高-左口-。未失也。婦子嘻嘻。失家節也。" aria-label="Permalink to “象曰。家人高高（左口）。未失也。婦子嘻嘻。失家節也。”">​</a></h3><p>失佚古通。未佚者言不敢放逸也。若嘻嘻則淫佚而不中節矣。故曰失家節。失。下讀得之失。上讀佚。以與節韻。</p><p>六四。富家大吉。</p><p>乾為富。四承重陽。當位有應。體坎。坎為室家。故曰富家大吉。凡上卦為巽。四當位無不吉者。如小言觀益巽渙中孚。六四皆吉。誰不當位者。雖臨重陽。不盡吉也。此易例也。虞翻旨命三變成艮。最為害理。三當位。胡為使失正哉。</p><h3 id="象曰。富家大吉。順在位也。" tabindex="-1">象曰。富家大吉。順在位也。 <a class="header-anchor" href="#象曰。富家大吉。順在位也。" aria-label="Permalink to “象曰。富家大吉。順在位也。”">​</a></h3><p>言富之故。以順陽也。五得位。故曰順在位。</p><p>九五。王假有家。勿恤。吉。</p><p>五天子。故曰王。假釋文更白反。注至也。案虞書。格子上下。傳。格至也。是王弼陸德明皆讀假為格。與萃之王假有廟同。王假有廟。言王以至誠感神明。王假有家。言王以至德威格家人。無有不正。故無所憂而吉也。</p><h3 id="象曰。王假有家。交相愛也。" tabindex="-1">象曰。王假有家。交相愛也。 <a class="header-anchor" href="#象曰。王假有家。交相愛也。" aria-label="Permalink to “象曰。王假有家。交相愛也。”">​</a></h3><p>交相愛。謂二五交孚。即釋格義。諸家皆釋假為大。與交相愛之義相去甚遠。故唯王注為得也。</p><p>上九。有孚。威如。終吉。</p><p>上九居家之上。為全家所戴。故曰有孚。曰威如。上居卦終。故曰終吉。</p><h3 id="象曰。威如之吉。反身之謂也。" tabindex="-1">象曰。威如之吉。反身之謂也。 <a class="header-anchor" href="#象曰。威如之吉。反身之謂也。" aria-label="Permalink to “象曰。威如之吉。反身之謂也。”">​</a></h3><p>巽究成震。震為威。言震巽相反覆。故曰反身。虞翻命三變成陰。以說反身。三當位。胡能使變。乃惠棟不知其強說。謂蹇上六志在內為反身。夫蹇三上皆當位有應與。若家人則三上皆陽。艮傳所謂敵應也。上胡能反三哉。</p>',29)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
